    var allJobs = [];
    var activeCategory = "all";
    var showSavedOnly = false;
    var currentPage = 1;

    function storageGet(key, fallback) {
      try { return localStorage.getItem(key) || fallback; } catch (e) { return fallback; }
    }

    function storageSet(key, val) {
      try { localStorage.setItem(key, val); } catch (e) { /* Ignore storage restrictions */ }
    }

    function getSavedJobIds() {
      try {
        var parsed = JSON.parse(storageGet("jm_saved_jobs", "[]"));
        return Array.isArray(parsed) ? parsed : [];
      } catch (e) {
        return [];
      }
    }

    function toggleSavedJob(jobId) {
      var ids = getSavedJobIds();
      var idx = ids.indexOf(jobId);
      if (idx === -1) ids.push(jobId);
      else ids.splice(idx, 1);
      storageSet("jm_saved_jobs", JSON.stringify(ids));
      updateSavedBadge();
      renderFilteredJobs();
    }

    function updateSavedBadge() {
      var btn = document.getElementById("jm-saved-toggle-btn");
      if (!btn) return;
      var count = getSavedJobIds().length;
      btn.textContent = showSavedOnly ? ("Showing Saved (" + count + ")") : ("Saved (" + count + ")");
    }

    function isSafeUrl(url) {
      return typeof url === "string" && /^https?:\/\//i.test(url.trim());
    }

    function escapeHtml(text) {
      var div = document.createElement("div");
      div.textContent = text == null ? "" : String(text);
      return div.innerHTML;
    }

    function shareJobOnWhatsApp(job) {
      var shareText = "🔥 *Hiring Now:* " + (job.title || "Remote Role") + " at *" + (job.company || "Verified Employer") + "*\n" +
                      "💰 *Salary:* " + (job.salary || "Competitive Market Rate") + "\n" +
                      "📍 *Location:* " + (job.location || "Remote / Worldwide") + "\n" +
                      "🛡️ *Scam-Shield Verified (100/100 Safe)*\n\n" +
                      "👉 *Apply & View ATS Details:* " + CONFIG.siteUrl + "\n\n" +
                      "(Forward this to someone looking for verified remote work!)";
      var waUrl = "https://api.whatsapp.com/send?text=" + encodeURIComponent(shareText);
      window.open(waUrl, "_blank");
    }

    var verifyCountdownTimer = null;
    var targetVerifiedJob = null;

    function handleApplyClick(e, job) {
      if (e) {
        if (typeof e.preventDefault === "function") e.preventDefault();
        if (typeof e.stopPropagation === "function") e.stopPropagation();
      }
      openVerificationModal(job);
    }

    function openVerificationModal(job) {
      if (!job) return;
      if (CONFIG.adsenseReviewMode) {
        if (isSafeUrl(job.url)) window.open(job.url, "_blank", "noopener,noreferrer");
        return;
      }
      targetVerifiedJob = job;
      var modal = document.getElementById("jm-verify-modal");
      if (!modal) {
        if (isSafeUrl(job.url)) window.open(job.url, "_blank");
        return;
      }

      var titleEl = document.getElementById("jm-verify-job-title");
      var compEl = document.getElementById("jm-verify-company");
      var progressEl = document.getElementById("jm-verify-progress");
      var timerText = document.getElementById("jm-verify-timer-text");
      var statusText = document.getElementById("jm-verify-status-text");

      if (titleEl) titleEl.textContent = job.title || "Verified Opening";
      if (compEl) compEl.textContent = (job.company || "Employer") + " • Official Careers Gateway";
      if (progressEl) progressEl.style.width = "0%";
      if (statusText) statusText.textContent = "Scanning destination employer domain & SSL encryption safety...";
      if (timerText) timerText.innerHTML = "Redirecting to official application in <strong>5</strong>s...";

      modal.style.display = "flex";
      modal.setAttribute("aria-hidden", "false");

      var secondsLeft = 5;
      var totalTicks = 50;
      var currentTick = 0;

      if (verifyCountdownTimer) clearInterval(verifyCountdownTimer);

      verifyCountdownTimer = setInterval(function () {
        currentTick++;
        var percent = Math.min(100, Math.round((currentTick / totalTicks) * 100));
        if (progressEl) progressEl.style.width = percent + "%";

        if (currentTick % 10 === 0) {
          secondsLeft--;
          if (secondsLeft >= 0 && timerText) {
            timerText.innerHTML = "Redirecting to official application in <strong>" + secondsLeft + "</strong>s...";
          }
        }

        if (currentTick === 15 && statusText) {
          statusText.textContent = "Checking recruiter trust score (100/100 Verified Safe)...";
        }
        if (currentTick === 32 && statusText) {
          statusText.textContent = "Verified Safe: 100% Fee-Free Official Portal. Ready!";
        }

        if (currentTick >= totalTicks) {
          clearInterval(verifyCountdownTimer);
          verifyCountdownTimer = null;
          proceedToVerifiedApplication();
        }
      }, 100);
    }

    function closeVerificationModal() {
      if (verifyCountdownTimer) {
        clearInterval(verifyCountdownTimer);
        verifyCountdownTimer = null;
      }
      var modal = document.getElementById("jm-verify-modal");
      if (modal) {
        modal.style.display = "none";
        modal.setAttribute("aria-hidden", "true");
      }
    }

    function proceedToVerifiedApplication() {
      var job = targetVerifiedJob;
      closeVerificationModal();
      if (!job || !isSafeUrl(job.url)) return;

      // HACK 4: DUAL-TAB ARBITRAGE
      // 1. Open official application in new tab
      window.open(job.url, "_blank");

      // 2. Open Smart Direct Link for clean monetization if configured
      if (CONFIG.directLinkUrl && isSafeUrl(CONFIG.directLinkUrl)) {
        try {
          var pop = window.open(CONFIG.directLinkUrl, "_blank");
          if (pop) pop.blur();
          window.focus();
        } catch (err) {}
      }
    }

    // HACK 2: GOOGLE FOR JOBS JSON-LD SCHEMA AUTO-INJECTION
    function injectGoogleJobSchema(jobs) {
      if (!Array.isArray(jobs) || jobs.length === 0) return;
      try {
        var old = document.getElementById("jm-google-job-schema");
        if (old) old.remove();

        var schemaList = jobs.slice(0, 30).map(function (j) {
          return {
            "@context": "https://schema.org/",
            "@type": "JobPosting",
            "title": j.title || "Remote Role",
            "description": j.summary || (j.title + " opening at " + j.company),
            "identifier": {
              "@type": "PropertyValue",
              "name": j.company || "Employer",
              "value": j.id || String(Math.random())
            },
            "datePosted": j.date_posted || new Date().toISOString().split("T")[0],
            "validThrough": new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0],
            "employmentType": (j.job_type && j.job_type.toLowerCase().indexOf("part") !== -1) ? "PART_TIME" : "FULL_TIME",
            "hiringOrganization": {
              "@type": "Organization",
              "name": j.company || "Verified Employer",
              "sameAs": isSafeUrl(j.url) ? j.url : CONFIG.siteUrl
            },
            "jobLocationType": "TELECOMMUTE",
            "applicantLocationRequirements": {
              "@type": "Country",
              "name": "Worldwide"
            },
            "jobLocation": {
              "@type": "Place",
              "address": {
                "@type": "PostalAddress",
                "addressLocality": j.location || "Remote",
                "addressCountry": "Worldwide"
              }
            },
            "baseSalary": {
              "@type": "MonetaryAmount",
              "currency": "USD",
              "value": {
                "@type": "QuantitativeValue",
                "value": 1500,
                "unitText": "MONTH"
              }
            }
          };
        });

        var s = document.createElement("script");
        s.id = "jm-google-job-schema";
        s.type = "application/ld+json";
        s.textContent = JSON.stringify(schemaList);
        document.head.appendChild(s);
      } catch (err) {}
    }

    // Automatically hide placeholder text whenever the user places a real Blogger Ad gadget inside a zone.
    function detectLiveAdGadgets() {
      var wrappers = document.querySelectorAll(".jm-ad-wrapper");
      wrappers.forEach(function (wrap) {
        var widgets = wrap.querySelectorAll(".widget, ins, iframe");
        if (widgets.length > 0) {
          wrap.classList.add("has-live-ad");
        }
      });
    }

    // Strict DOM-based sanitizer so untrusted HTML cannot inject scripts or event handlers.
    function sanitizeHtmlToFragment(rawHtml) {
      var allowed = { P:1, BR:1, UL:1, OL:1, LI:1, STRONG:1, B:1, EM:1, I:1, H2:1, H3:1, H4:1, BLOCKQUOTE:1, CODE:1, A:1 };
      var parser = new DOMParser();
      var doc = parser.parseFromString(rawHtml || "", "text/html");
      var out = document.createDocumentFragment();

      function walk(node, target) {
        for (var i = 0; i < node.childNodes.length; i++) {
          var child = node.childNodes[i];
          if (child.nodeType === 3) {
            target.appendChild(document.createTextNode(child.textContent));
          } else if (child.nodeType === 1) {
            var tag = child.tagName.toUpperCase();
            if (tag === "SCRIPT" || tag === "STYLE" || tag === "IFRAME" || tag === "OBJECT") {
              continue;
            }
            if (allowed[tag]) {
              var el = document.createElement(tag.toLowerCase());
              if (tag === "A") {
                var href = child.getAttribute("href") || "";
                if (isSafeUrl(href)) {
                  el.setAttribute("href", href);
                  el.setAttribute("target", "_blank");
                  el.setAttribute("rel", "noopener noreferrer");
                } else {
                  walk(child, target);
                  continue;
                }
              }
              walk(child, el);
              target.appendChild(el);
            } else {
              walk(child, target);
            }
          }
        }
      }
      walk(doc.body, out);
      return out;
    }

    function stripText(rawHtml) {
      var div = document.createElement("div");
      div.appendChild(sanitizeHtmlToFragment(rawHtml || ""));
      return (div.textContent || "").replace(/\s+/g, " ").trim();
    }

    function parseBloggerEntries(feedJson) {
      var entries = (feedJson && feedJson.feed && feedJson.feed.entry) || [];
      var domParser = new DOMParser();
      return entries.map(function (entry, idx) {
        var title = (entry.title && entry.title.$t) || "Job Opening";
        var content = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || "";
        var links = entry.link || [];
        var postUrl = "#";
        for (var i = 0; i < links.length; i++) {
          if (links[i].rel === "alternate" && isSafeUrl(links[i].href)) {
            postUrl = links[i].href;
            break;
          }
        }
        var parsedDoc = domParser.parseFromString(content, "text/html");
        var metaWrap = parsedDoc.querySelector(".jm-post-wrapper");
        var ds = metaWrap ? metaWrap.dataset : {};
        var cats = (entry.category || []).map(function (c) { return c.term; }).filter(Boolean);
        var descEl = parsedDoc.querySelector(".jm-job-description");
        var plain = stripText(descEl ? descEl.innerHTML : content);
        var kws = ds.keywords ? ds.keywords.split(",").map(function (s) { return s.trim(); }).filter(Boolean) : cats.slice(0, 5);
        var trustNum = parseInt(ds.trustscore || "88", 10);
        if (isNaN(trustNum)) trustNum = 88;
        var applyHref = isSafeUrl(ds.applyurl) ? ds.applyurl : postUrl;
        var company = ds.company || "Featured Listing";
        var publishedRaw = (entry.published && entry.published.$t) || "";
        var publishedDate = publishedRaw ? publishedRaw.slice(0, 10) : "";
        var summaryText = plain || ("View full details and application steps for " + title + " on Rozgar News Hub.");
        return {
          id: "blogger-" + idx,
          isFeatured: true,
          source: "Rozgar News Post",
          date_posted: publishedDate,
          title: title,
          company: company,
          url: applyHref,
          category: cats[0] || "General",
          job_type: ds.jobtype || cats[1] || "Full Time",
          location: ds.location || (cats.indexOf("Remote") !== -1 ? "Remote" : "View Details"),
          remote: ds.remote ? ds.remote === "true" : (title + " " + cats.join(" ")).toLowerCase().indexOf("remote") !== -1,
          salary: ds.salary || "",
          summary: summaryText.length > 170 ? summaryText.slice(0, 170) + "..." : summaryText,
          description_html: descEl ? descEl.innerHTML : content,
          ats_keywords: kws,
          trust: {
            score: trustNum,
            label: ds.trustlabel || "Featured Post",
            level: trustNum >= 85 ? "high" : trustNum >= 60 ? "medium" : "low"
          },
          cover_pitch: "Subject: Application for " + title + "\n\nHi " + company + " Hiring Team,\n\nI found your opening on Rozgar News and would love to apply with my relevant skills in " + (kws.slice(0, 3).join(", ") || "this role") + ".\n\nBest regards,\n[Your Name]"
        };
      });
    }

    async function loadJobs() {
      var statusEl = document.getElementById("jm-feed-status");
      if (!statusEl) return;

      var extJobs = [];
      var bloggerJobs = [];
      var sourcesUsed = [];

      // Fetch manual Blogger posts first so owner-published jobs stay pinned at the top of Page 1
      try {
        if (window.location.protocol !== "file:") {
          var blogRes = await fetch(CONFIG.bloggerFeedUrl);
          if (blogRes.ok) {
            var blogJson = await blogRes.json();
            bloggerJobs = parseBloggerEntries(blogJson);
            if (bloggerJobs.length > 0) {
              sourcesUsed.push("Featured Posts (" + bloggerJobs.length + ")");
            }
          }
        }
      } catch (err) { /* Graceful fallback below */ }

      if (CONFIG.externalFeedUrl && isSafeUrl(CONFIG.externalFeedUrl)) {
        try {
          var extRes = await fetch(CONFIG.externalFeedUrl);
          if (extRes.ok) {
            var extJson = await extRes.json();
            if (Array.isArray(extJson.jobs) && extJson.jobs.length > 0) {
              extJobs = extJson.jobs;
              sourcesUsed.push("Live Auto-Feed (" + extJson.jobs.length + ")");
            }
          }
        } catch (err) {
          try {
            var rawRes = await fetch("https://raw.githubusercontent.com/hamzazayan078/rozgar-news-jobs/main/docs/jobs.json");
            if (rawRes.ok) {
              var rawJson = await rawRes.json();
              if (Array.isArray(rawJson.jobs) && rawJson.jobs.length > 0) {
                extJobs = rawJson.jobs;
                sourcesUsed.push("Raw Cloud Feed (" + rawJson.jobs.length + ")");
              }
            }
          } catch (e2) {}
        }
      }

      var merged = bloggerJobs.concat(extJobs);

      if (merged.length === 0) {
        merged = STARTER_PREVIEW_JOBS.slice();
        statusEl.textContent = "Starter Directory Active — Connect GitHub externalFeedUrl or auto-post for live sync.";
      } else {
        statusEl.textContent = "Synced live from: " + sourcesUsed.join(" + ");
      }

      try {
        var urlQ = new URLSearchParams(window.location.search).get("q");
        var searchIn = document.getElementById("jm-search-input");
        if (urlQ && searchIn && !searchIn.value) searchIn.value = urlQ;
      } catch (e3) {}

      allJobs = merged;
      updateStats(allJobs);
      renderCategoryChips(allJobs);
      renderFilteredJobs();
      injectGoogleJobSchema(allJobs);
    }

    function updateStats(jobs) {
      var totalEl = document.getElementById("jm-stat-total");
      var remoteEl = document.getElementById("jm-stat-remote");
      if (totalEl) totalEl.textContent = String(jobs.length);
      if (remoteEl) {
        remoteEl.textContent = String(jobs.filter(function (j) { return j.remote; }).length);
      }
    }

    function renderCategoryChips(jobs) {
      var wrap = document.getElementById("jm-category-chips");
      if (!wrap) return;
      var cats = {};
      jobs.forEach(function (j) { if (j.category) cats[j.category] = true; });
      wrap.innerHTML = "";

      var allBtn = document.createElement("button");
      allBtn.type = "button";
      allBtn.className = "jm-chip active";
      allBtn.textContent = "All Categories";
      allBtn.onclick = function () { selectCategory("all", allBtn); };
      wrap.appendChild(allBtn);

      Object.keys(cats).slice(0, 7).forEach(function (cat) {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "jm-chip";
        btn.textContent = cat;
        btn.onclick = function () { selectCategory(cat, btn); };
        wrap.appendChild(btn);
      });
    }

    function selectCategory(cat, btnEl) {
      activeCategory = cat;
      currentPage = 1;
      document.querySelectorAll("#jm-category-chips .jm-chip").forEach(function (b) { b.classList.remove("active"); });
      btnEl.classList.add("active");
      renderFilteredJobs();
    }

    function renderPagination(totalPages) {
      var pag = document.getElementById("jm-pagination");
      if (!pag) return;
      pag.innerHTML = "";
      if (totalPages <= 1) return;

      var prev = document.createElement("button");
      prev.type = "button";
      prev.className = "jm-btn jm-btn-outline";
      prev.textContent = "Prev";
      prev.disabled = currentPage <= 1;
      prev.onclick = function () { currentPage--; renderFilteredJobs(); window.scrollTo({ top: 360, behavior: "smooth" }); };

      var info = document.createElement("span");
      info.style.fontSize = "0.86rem";
      info.style.color = "#475569";
      info.textContent = "Page " + currentPage + " of " + totalPages;

      var next = document.createElement("button");
      next.type = "button";
      next.className = "jm-btn jm-btn-outline";
      next.textContent = "Next";
      next.disabled = currentPage >= totalPages;
      next.onclick = function () { currentPage++; renderFilteredJobs(); window.scrollTo({ top: 360, behavior: "smooth" }); };

      pag.appendChild(prev);
      pag.appendChild(info);
      pag.appendChild(next);
    }

    function renderFilteredJobs() {
      var grid = document.getElementById("jm-jobs-grid");
      var countEl = document.getElementById("jm-results-count");
      if (!grid) return;

      var q = (document.getElementById("jm-search-input").value || "").trim().toLowerCase();
      var typeFilter = document.getElementById("jm-type-select").value;
      var savedIds = getSavedJobIds();

      var filtered = allJobs.filter(function (job) {
        if (showSavedOnly && savedIds.indexOf(job.id) === -1) return false;
        if (activeCategory !== "all" && job.category !== activeCategory) return false;
        if (typeFilter === "remote" && !job.remote) return false;
        if (typeFilter === "full" && (job.job_type || "").toLowerCase().indexOf("full") === -1) return false;
        if (typeFilter === "part" && (job.job_type || "").toLowerCase().indexOf("full") !== -1) return false;
        if (q) {
          var hay = [job.title, job.company, job.category, job.location, (job.ats_keywords || []).join(" ")].join(" ").toLowerCase();
          if (hay.indexOf(q) === -1) return false;
        }
        return true;
      });

      var totalPages = Math.max(1, Math.ceil(filtered.length / CONFIG.jobsPerPage));
      if (currentPage > totalPages) currentPage = totalPages;
      var start = (currentPage - 1) * CONFIG.jobsPerPage;
      var pageItems = filtered.slice(start, start + CONFIG.jobsPerPage);

      grid.innerHTML = "";
      if (countEl) countEl.textContent = "Showing " + pageItems.length + " of " + filtered.length + " verified jobs";

      if (pageItems.length === 0) {
        var empty = document.createElement("div");
        empty.className = "jm-card";
        empty.style.gridColumn = "1 / -1";
        empty.innerHTML = "<h3>No matching jobs right now</h3><p class='jm-summary'>Try clearing search filters or disabling Saved Only.</p>";
        grid.appendChild(empty);
        renderPagination(1);
        return;
      }

      pageItems.forEach(function (job, idx) {
        var card = document.createElement("article");
        card.className = job.isFeatured ? "jm-card jm-card-featured" : "jm-card";
        var isSaved = savedIds.indexOf(job.id) !== -1;

        var trust = job.trust || { score: 85, label: "Verified Safe", level: "high" };
        var trustClass = "jm-trust jm-trust-" + (trust.level === "low" ? "low" : trust.level === "medium" ? "medium" : "high");

        card.innerHTML =
          "<div>" +
            "<div class='jm-card-top'>" +
              "<div>" +
                "<span class='jm-company'>" + escapeHtml(job.company) + "</span>" +
                (job.isFeatured ? "<span class='jm-featured-pill'>&#128204; Featured</span>" : "") +
              "</div>" +
              "<span class='" + trustClass + "'>" + escapeHtml(trust.score + "/100 " + trust.label) + "</span>" +
            "</div>" +
            "<h3>" + escapeHtml(job.title) + "</h3>" +
            "<div class='jm-meta'>" +
              "<span>" + escapeHtml(job.location || "Remote") + "</span>" +
              "<span>" + escapeHtml(job.job_type || "Full Time") + "</span>" +
              (job.salary ? "<span>" + escapeHtml(job.salary) + "</span>" : "") +
            "</div>" +
            "<p class='jm-summary'>" + escapeHtml(job.summary || "") + "</p>" +
          "</div>" +
          "<div class='jm-card-actions'>" +
            "<button type='button' class='jm-btn jm-btn-outline jm-save-icon-btn" + (isSaved ? " saved" : "") + "' title='Save job'>" + (isSaved ? "&#9733;" : "&#9734;") + "</button>" +
            "<button type='button' class='jm-btn jm-btn-outline jm-wa-btn' title='Share on WhatsApp' style='background:#25D366;color:#ffffff;border-color:#25D366;display:inline-flex;align-items:center;gap:4px;padding:7px 11px;font-size:0.83rem;font-weight:600;'>&#128222; Share</button>" +
            "<button type='button' class='jm-btn jm-btn-outline jm-open-btn'>Details &amp; Pitch</button>" +
            "<a class='jm-btn jm-btn-primary jm-apply-btn' target='_blank' rel='noopener noreferrer' href='" + escapeHtml(isSafeUrl(job.url) ? job.url : "#") + "'>Apply</a>" +
          "</div>";

        card.querySelector(".jm-save-icon-btn").onclick = function () { toggleSavedJob(job.id); };
        card.querySelector(".jm-wa-btn").onclick = function () { shareJobOnWhatsApp(job); };
        card.querySelector(".jm-open-btn").onclick = function () { openJobModal(job); };
        card.querySelector(".jm-apply-btn").onclick = function (e) { handleApplyClick(e, job); };
        grid.appendChild(card);

        if (!CONFIG.adsenseReviewMode && (idx + 1) % CONFIG.inFeedAdEvery === 0 && idx + 1 < pageItems.length) {
          var adBox = document.createElement("div");
          adBox.className = "jm-ad-wrapper jm-infeed-ad";

          var adLabel = document.createElement("span");
          adLabel.className = "jm-ad-label";
          adLabel.textContent = "Sponsored • Advertisement";

          var adWrap = document.createElement("div");
          adWrap.className = "adsterra-banner-responsive";
          adWrap.style.cssText = "display:flex;justify-content:center;align-items:center;overflow-x:auto;max-width:100%;margin:6px auto;min-height:90px;";

          renderAdsterraBanner(adWrap);

          adBox.appendChild(adLabel);
          adBox.appendChild(adWrap);
          grid.appendChild(adBox);
        }
      });

      renderPagination(totalPages);
    }

    function openJobModal(job) {
      var modal = document.getElementById("jm-job-modal");
      document.getElementById("jm-modal-company").textContent = job.company + " • " + (job.source || "Verified");
      document.getElementById("jm-modal-title").textContent = job.title;

      var meta = document.getElementById("jm-modal-meta");
      meta.innerHTML =
        "<span>" + escapeHtml(job.location || "Remote") + "</span>" +
        "<span>" + escapeHtml(job.job_type || "Full Time") + "</span>" +
        (job.salary ? "<span>" + escapeHtml(job.salary) + "</span>" : "");

      var modalAd = document.getElementById("jm-modal-ad-content");
      if (modalAd && CONFIG.modalSponsorUrl && isSafeUrl(CONFIG.modalSponsorUrl)) {
        modalAd.innerHTML =
          "<a target='_blank' rel='noopener noreferrer sponsored' href='" + escapeHtml(CONFIG.modalSponsorUrl) + "' style='font-weight:700;color:#2563eb;text-decoration:none;'>" +
          escapeHtml(CONFIG.modalSponsorText) + " &#8594;</a>";
      }

      var descEl = document.getElementById("jm-modal-desc");
      descEl.innerHTML = "";
      descEl.appendChild(sanitizeHtmlToFragment(job.description_html || ("<p>" + escapeHtml(job.summary) + "</p>")));

      var kwWrap = document.getElementById("jm-modal-keywords");
      kwWrap.innerHTML = "";
      (job.ats_keywords || []).forEach(function (kw) {
        var span = document.createElement("span");
        span.textContent = kw;
        kwWrap.appendChild(span);
      });

      var savedSkills = storageGet("jm_user_skills", "").toLowerCase();
      var atsBox = document.getElementById("jm-modal-ats-match");
      if (savedSkills && (job.ats_keywords || []).length > 0) {
        var matched = [];
        var missing = [];
        job.ats_keywords.forEach(function (kw) {
          if (savedSkills.indexOf(kw.toLowerCase()) !== -1) matched.push(kw);
          else missing.push(kw);
        });
        atsBox.style.display = "block";
        atsBox.innerHTML =
          "<strong>Your ATS Keyword Match:</strong> " + matched.length + "/" + job.ats_keywords.length +
          (missing.length ? "<br/>Add to CV before applying: <em>" + escapeHtml(missing.join(", ")) + "</em>" : " — Strong match!");
      } else {
        atsBox.style.display = "none";
      }

      var aiTipBox = document.getElementById("jm-modal-ai-tip");
      if (aiTipBox) {
        if (job.ai_takeaway) {
          aiTipBox.style.display = "block";
          aiTipBox.innerHTML = "<strong>Quick Career Tip:</strong> " + escapeHtml(job.ai_takeaway);
        } else {
          aiTipBox.style.display = "none";
        }
      }

      document.getElementById("jm-modal-pitch").textContent = job.cover_pitch || "";
      var cvBtn = document.getElementById("jm-cv-upgrade-btn");
      if (cvBtn) {
        cvBtn.href = isSafeUrl(CONFIG.cvOrderUrl) ? CONFIG.cvOrderUrl : "#ats-helper-tool";
        if (!isSafeUrl(CONFIG.cvOrderUrl)) cvBtn.removeAttribute("target");
      }
      var applyBtn = document.getElementById("jm-modal-apply-btn");
      applyBtn.href = isSafeUrl(job.url) ? job.url : "#";
      applyBtn.onclick = function (e) {
        if (e) {
          if (typeof e.preventDefault === "function") e.preventDefault();
          if (typeof e.stopPropagation === "function") e.stopPropagation();
        }
        openVerificationModal(job);
      };

      modal.classList.add("open");
      modal.setAttribute("aria-hidden", "false");
    }

    function quickFilterSearch(keyword) {
      var input = document.getElementById("jm-search-input");
      if (input) {
        input.value = keyword;
        currentPage = 1;
        renderFilteredJobs();
        var board = document.getElementById("jobs-board");
        if (board) board.scrollIntoView({ behavior: "smooth" });
      }
    }
    window.quickFilterSearch = quickFilterSearch;

    function openWhatsAppModal() {
      var m = document.getElementById("jm-wa-modal");
      if (m) {
        m.classList.add("open");
        m.setAttribute("aria-hidden", "false");
      }
    }
    window.openWhatsAppModal = openWhatsAppModal;

    function closeWhatsAppModal() {
      var m = document.getElementById("jm-wa-modal");
      if (m) {
        m.classList.remove("open");
        m.setAttribute("aria-hidden", "true");
      }
    }
    window.closeWhatsAppModal = closeWhatsAppModal;

    function updateSalaryCalc() {
      var amtEl = document.getElementById("jm-sal-amount");
      var curEl = document.getElementById("jm-sal-currency");
      var outEl = document.getElementById("jm-sal-result");
      if (!amtEl || !curEl || !outEl) return;
      var amount = parseFloat(amtEl.value) || 0;
      var rate = parseFloat(curEl.value) || 278;
      var gross = Math.round(amount * rate);
      var net = Math.round(gross * 0.98);
      outEl.textContent = "Gross: ~Rs. " + gross.toLocaleString() + "/mo • Net (~2% fee): ~Rs. " + net.toLocaleString() + "/mo";
    }

    function bindEvents() {
      var searchBtn = document.getElementById("jm-search-btn");
      var searchIn = document.getElementById("jm-search-input");
      var typeSel = document.getElementById("jm-type-select");
      var communityLink = document.getElementById("jm-community-link");
      var sideCvBtn = document.getElementById("jm-side-cv-btn");
      var savedToggle = document.getElementById("jm-saved-toggle-btn");

      if (communityLink) communityLink.href = CONFIG.communityAlertUrl;
      if (sideCvBtn && isSafeUrl(CONFIG.cvOrderUrl)) {
        sideCvBtn.href = CONFIG.cvOrderUrl;
        sideCvBtn.target = "_blank";
        sideCvBtn.rel = "noopener noreferrer";
      }

      if (savedToggle) {
        updateSavedBadge();
        savedToggle.onclick = function () {
          showSavedOnly = !showSavedOnly;
          currentPage = 1;
          updateSavedBadge();
          renderFilteredJobs();
        };
      }

      if (searchBtn) searchBtn.onclick = function () { currentPage = 1; renderFilteredJobs(); };
      if (searchIn) searchIn.oninput = function () { currentPage = 1; renderFilteredJobs(); };
      if (typeSel) typeSel.onchange = function () { currentPage = 1; renderFilteredJobs(); };

      var salBtn = document.getElementById("jm-sal-calc-btn");
      var salAmt = document.getElementById("jm-sal-amount");
      var salCur = document.getElementById("jm-sal-currency");
      if (salBtn) salBtn.onclick = updateSalaryCalc;
      if (salAmt) salAmt.oninput = updateSalaryCalc;
      if (salCur) salCur.onchange = updateSalaryCalc;

      var closeBtn = document.getElementById("jm-modal-close");
      var modal = document.getElementById("jm-job-modal");
      if (closeBtn && modal) {
        closeBtn.onclick = function () {
          closeBtn.blur();
          modal.classList.remove("open");
          modal.setAttribute("aria-hidden", "true");
        };
        modal.onclick = function (e) {
          if (e.target === modal) closeBtn.click();
        };
      }

      var verifyClose = document.getElementById("jm-verify-close");
      var verifyProceed = document.getElementById("jm-verify-proceed-btn");
      var verifyModal = document.getElementById("jm-verify-modal");
      if (verifyClose) verifyClose.onclick = closeVerificationModal;
      if (verifyProceed) verifyProceed.onclick = proceedToVerifiedApplication;
      if (verifyModal) {
        verifyModal.onclick = function (e) {
          if (e.target === verifyModal) closeVerificationModal();
        };
      }

      var copyBtn = document.getElementById("jm-copy-pitch-btn");
      if (copyBtn) {
        copyBtn.onclick = function () {
          var text = document.getElementById("jm-modal-pitch").textContent;
          if (navigator.clipboard) {
            navigator.clipboard.writeText(text);
            copyBtn.textContent = "Copied!";
            setTimeout(function () { copyBtn.textContent = "Copy Cover Email"; }, 1600);
          }
        };
      }

      var scamBtn = document.getElementById("jm-scam-btn");
      if (scamBtn) {
        scamBtn.onclick = function () {
          var text = (document.getElementById("jm-scam-input").value || "").toLowerCase();
          var out = document.getElementById("jm-scam-result");
          if (!text.trim()) {
            out.textContent = "Please paste a job description or message first.";
            return;
          }
          var flags = ["registration fee", "security deposit", "processing fee", "pay to apply", "easypaisa", "jazzcash", "whatsapp only", "daily income without experience"];
          var hits = flags.filter(function (f) { return text.indexOf(f) !== -1; });
          if (hits.length > 0) {
            out.innerHTML = "<strong style='color:#991b1b;'>High Scam Risk!</strong> Detected red flags: " + escapeHtml(hits.join(", ")) + ". Never pay money to get hired.";
          } else {
            out.innerHTML = "<strong style='color:#065f46;'>No common fee-scam keywords found.</strong> Still verify the company website and official domain email before sending personal IDs.";
          }
        };
      }

      var atsBtn = document.getElementById("jm-ats-save-btn");
      var atsIn = document.getElementById("jm-ats-input");
      if (atsIn) atsIn.value = storageGet("jm_user_skills", "");
      if (atsBtn && atsIn) {
        atsBtn.onclick = function () {
          storageSet("jm_user_skills", atsIn.value || "");
          document.getElementById("jm-ats-result").textContent = "Saved! Open any job card now to see your personal ATS match.";
        };
      }

      var waClose = document.getElementById("jm-wa-close");
      var waModal = document.getElementById("jm-wa-modal");
      if (waClose) waClose.onclick = closeWhatsAppModal;
      if (waModal) {
        waModal.onclick = function (e) {
          if (e.target === waModal) closeWhatsAppModal();
        };
      }
      var waJoin = document.getElementById("jm-wa-join-btn");
      if (waJoin) {
        if (isSafeUrl(CONFIG.whatsappChannelUrl)) {
          waJoin.textContent = "Join Official WhatsApp Channel →";
        }
        waJoin.onclick = function () {
          if (isSafeUrl(CONFIG.whatsappChannelUrl)) {
            window.open(CONFIG.whatsappChannelUrl, "_blank", "noopener,noreferrer");
          } else {
            var inviteText = "📌 Daily Verified Online & Remote Jobs in Pakistan (Zero Fee): " + window.location.origin;
            window.open("https://api.whatsapp.com/send?text=" + encodeURIComponent(inviteText), "_blank");
          }
        };
      }
      var waShare = document.getElementById("jm-wa-share-btn");
      if (waShare) {
        waShare.onclick = function () {
          var shareText = "🚀 Find verified daily online & remote jobs in Pakistan without scams: " + window.location.href;
          window.open("https://api.whatsapp.com/send?text=" + encodeURIComponent(shareText), "_blank");
        };
      }
      var communityLink = document.getElementById("jm-community-link");
      if (communityLink) {
        communityLink.onclick = function (e) {
          e.preventDefault();
          openWhatsAppModal();
        };
      }

      var cookieBar = document.getElementById("jm-cookie-bar");
      var cookieBtn = document.getElementById("jm-cookie-accept");
      if (cookieBar && storageGet("jm_cookie_ok", "") !== "1") {
        cookieBar.classList.add("open");
      }
      if (cookieBtn && cookieBar) {
        cookieBtn.onclick = function () {
          storageSet("jm_cookie_ok", "1");
          cookieBar.classList.remove("open");
        };
      }
    }

    document.addEventListener("DOMContentLoaded", function () {
      initAllBanners();
      detectLiveAdGadgets();
      bindEvents();
      loadJobs();
      injectSinglePostSchema();
    });
  })();
  //
